-- ============================================================
-- Server-created Paddle checkout orders
-- UUID is generated by Java with UUID.randomUUID().
-- ============================================================

CREATE TABLE paddle_checkout_orders (
    id                         UUID PRIMARY KEY,
    user_id                    BIGINT       NOT NULL REFERENCES users(id),
    plan_id                    BIGINT       NOT NULL REFERENCES plans(id),

    -- Price snapshot at checkout creation time
    expected_price_id          VARCHAR(100) NOT NULL,
    expected_subtotal_cents    BIGINT       NOT NULL
        CHECK (expected_subtotal_cents > 0),
    expected_currency          VARCHAR(3)   NOT NULL
        CHECK (expected_currency ~ '^[A-Z]{3}$'),

    -- Null until Paddle creates the transaction
    paddle_transaction_id      VARCHAR(100) UNIQUE,

    status                     VARCHAR(30)  NOT NULL DEFAULT 'PENDING'
        CHECK (status IN (
            'PENDING',
            'READY',
            'COMPLETED',
            'EXPIRED',
            'CANCELLED',
            'FAILED'
        )),

    expires_at                 TIMESTAMPTZ  NOT NULL,
    completed_at               TIMESTAMPTZ,
    failure_reason             TEXT,

    created_at                 TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at                 TIMESTAMPTZ
);

CREATE INDEX idx_paddle_checkout_orders_user
    ON paddle_checkout_orders(user_id);

CREATE INDEX idx_paddle_checkout_orders_plan
    ON paddle_checkout_orders(plan_id);

CREATE INDEX idx_paddle_checkout_orders_pending
    ON paddle_checkout_orders(status, expires_at)
    WHERE status IN ('PENDING', 'READY');


-- ============================================================
-- Durable webhook inbox
-- The controller returns HTTP 200 only after this row commits.
-- ============================================================

CREATE TABLE paddle_webhook_events (
    id                         BIGSERIAL PRIMARY KEY,

    event_id                   VARCHAR(100) NOT NULL UNIQUE,
    notification_id            VARCHAR(100),
    event_type                 VARCHAR(100) NOT NULL,
    occurred_at                TIMESTAMPTZ  NOT NULL,

    -- WEBHOOK or RECONCILIATION
    source                     VARCHAR(30)  NOT NULL DEFAULT 'WEBHOOK'
        CHECK (source IN ('WEBHOOK', 'RECONCILIATION')),

    payload                    JSONB        NOT NULL,

    status                     VARCHAR(30)  NOT NULL DEFAULT 'RECEIVED'
        CHECK (status IN (
            'RECEIVED',
            'PROCESSING',
            'RETRY',
            'PROCESSED',
            'DEAD_LETTER',
            'IGNORED'
        )),

    attempt_count              INT          NOT NULL DEFAULT 0
        CHECK (attempt_count >= 0),

    next_attempt_at            TIMESTAMPTZ,
    processing_started_at      TIMESTAMPTZ,

    -- Used as a lease if multiple application instances process events
    processing_owner           VARCHAR(100),
    processing_lease_until     TIMESTAMPTZ,

    last_error                 TEXT,
    processed_at               TIMESTAMPTZ,

    created_at                 TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    updated_at                 TIMESTAMPTZ
);

CREATE INDEX idx_paddle_webhook_events_processing
    ON paddle_webhook_events(status, next_attempt_at, occurred_at)
    WHERE status IN ('RECEIVED', 'RETRY');

CREATE INDEX idx_paddle_webhook_events_expired_lease
    ON paddle_webhook_events(processing_lease_until)
    WHERE status = 'PROCESSING';

CREATE INDEX idx_paddle_webhook_events_type
    ON paddle_webhook_events(event_type, occurred_at);

CREATE INDEX idx_paddle_webhook_events_dead_letter
    ON paddle_webhook_events(created_at)
    WHERE status = 'DEAD_LETTER';

CREATE INDEX idx_paddle_webhook_events_payload
    ON paddle_webhook_events USING GIN(payload);


-- ============================================================
-- Refunds, credits, chargebacks and reversals
-- The webhook inbox retains the complete event history.
-- This table stores the latest adjustment state.
-- ============================================================

CREATE TABLE paddle_adjustments (
    id                         BIGSERIAL PRIMARY KEY,

    paddle_adjustment_id       VARCHAR(100) NOT NULL UNIQUE,
    paddle_transaction_id      VARCHAR(100) NOT NULL,

    payment_id                 BIGINT       NOT NULL
        REFERENCES payments(id),

    last_webhook_event_id      BIGINT
        REFERENCES paddle_webhook_events(id)
        ON DELETE SET NULL,

    action                     VARCHAR(40)  NOT NULL
        CHECK (action IN (
            'CREDIT',
            'REFUND',
            'CHARGEBACK',
            'CHARGEBACK_REVERSE',
            'CHARGEBACK_WARNING',
            'CHARGEBACK_WARNING_REVERSE',
            'CREDIT_REVERSE'
        )),

    adjustment_type            VARCHAR(20)
        CHECK (
            adjustment_type IS NULL
            OR adjustment_type IN ('FULL', 'PARTIAL')
        ),

    status                     VARCHAR(30) NOT NULL
        CHECK (status IN (
            'PENDING_APPROVAL',
            'APPROVED',
            'REJECTED',
            'REVERSED'
        )),

    amount_cents               BIGINT      NOT NULL
        CHECK (amount_cents > 0),

    currency                   VARCHAR(3)  NOT NULL
        CHECK (currency ~ '^[A-Z]{3}$'),

    payload                    JSONB       NOT NULL,

    provider_created_at        TIMESTAMPTZ,
    provider_updated_at        TIMESTAMPTZ,
    processed_at               TIMESTAMPTZ,

    created_at                 TIMESTAMPTZ NOT NULL DEFAULT NOW(),
    updated_at                 TIMESTAMPTZ
);

CREATE INDEX idx_paddle_adjustments_payment
    ON paddle_adjustments(payment_id);

CREATE INDEX idx_paddle_adjustments_transaction
    ON paddle_adjustments(paddle_transaction_id);

CREATE INDEX idx_paddle_adjustments_status
    ON paddle_adjustments(status, provider_updated_at);

CREATE INDEX idx_paddle_adjustments_payload
    ON paddle_adjustments USING GIN(payload);


-- ============================================================
-- Immutable access entitlement ledger
--
-- duration_seconds_delta:
--   positive = access was added
--   negative = remaining access was removed
--
-- Store subscription end before/after every modification so that
-- payment access changes remain auditable.
-- ============================================================

CREATE TABLE payment_entitlement_ledger (
    id                              BIGSERIAL PRIMARY KEY,

    user_id                         BIGINT      NOT NULL
        REFERENCES users(id),

    payment_id                      BIGINT      NOT NULL
        REFERENCES payments(id),

    adjustment_id                   BIGINT
        REFERENCES paddle_adjustments(id),

    webhook_event_id                BIGINT
        REFERENCES paddle_webhook_events(id)
        ON DELETE SET NULL,

    entry_type                      VARCHAR(40) NOT NULL
        CHECK (entry_type IN (
            'PAYMENT_GRANT',
            'REFUND_REVOCATION',
            'CHARGEBACK_REVOCATION',
            'CHARGEBACK_REVERSAL'
        )),

    duration_seconds_delta          BIGINT      NOT NULL
        CHECK (duration_seconds_delta <> 0),

    subscription_end_before         TIMESTAMPTZ,
    subscription_end_after          TIMESTAMPTZ,

    -- Examples:
    -- payment:123:grant
    -- adjustment:adj_123
    idempotency_key                 VARCHAR(200) NOT NULL UNIQUE,

    reason                          TEXT,
    effective_at                    TIMESTAMPTZ  NOT NULL DEFAULT NOW(),
    created_at                      TIMESTAMPTZ  NOT NULL DEFAULT NOW(),

    CONSTRAINT chk_entitlement_delta_direction CHECK (
        (
            entry_type = 'PAYMENT_GRANT'
            AND duration_seconds_delta > 0
        )
        OR
        (
            entry_type IN (
                'REFUND_REVOCATION',
                'CHARGEBACK_REVOCATION'
            )
            AND duration_seconds_delta < 0
        )
        OR
        (
            entry_type = 'CHARGEBACK_REVERSAL'
            AND duration_seconds_delta > 0
        )
    )
);

-- One original access grant per payment
CREATE UNIQUE INDEX uq_payment_entitlement_original_grant
    ON payment_entitlement_ledger(payment_id)
    WHERE entry_type = 'PAYMENT_GRANT';

-- An adjustment must affect access at most once
CREATE UNIQUE INDEX uq_payment_entitlement_adjustment
    ON payment_entitlement_ledger(adjustment_id)
    WHERE adjustment_id IS NOT NULL;

CREATE INDEX idx_payment_entitlement_user
    ON payment_entitlement_ledger(user_id, effective_at);

CREATE INDEX idx_payment_entitlement_payment
    ON payment_entitlement_ledger(payment_id, effective_at);


-- ============================================================
-- Prevent blank provider transaction IDs in existing payments.
-- ============================================================

ALTER TABLE payments
    ADD CONSTRAINT chk_payments_provider_transaction_id_not_blank
    CHECK (BTRIM(provider_transaction_id) <> '');

CREATE INDEX idx_payments_provider_and_transaction
    ON payments(provider, provider_transaction_id);